// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0));
        c.Initialized();
        vm.prank(address(0xBEEF));
        bool ok = true;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "SetLogFile must be frozen after initialization");
    }
}
